def p(text,style='body'):return Paragraph(text,styles[style])
def block(title,text):return KeepTogether([p(title,'h2'),p(text)])
def table(rows,widths,header=True):
 t=Table([[p(c,'small' if i else 'label') for c in row] for i,row in enumerate(rows)],colWidths=widths,hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),LIGHT),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),10),('RIGHTPADDING',(0,0),(-1,-1),10),('TOPPADDING',(0,0),(-1,-1),9),('BOTTOMPADDING',(0,0),(-1,-1),7),('LINEBELOW',(0,0),(-1,-1),.4,HexColor('#D9E1DB'))]))
 return t
